/* Palette: #2c3e50 (dark blue), #ecf0f1 (light grey), #e67e22 (orange), #27ae60 (green), #c0392b (red) */

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  background: #2c3e50;
  color: #2c3e50;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #ecf0f1;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #2c3e50;
  margin-bottom: 8px;
  text-align: center;
}

.subtitle {
  font-size: 1rem;
  color: #555;
  text-align: center;
  margin-bottom: 24px;
}

.field-group {
  margin-bottom: 20px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  color: #2c3e50;
}

.input-wrapper {
  display: flex;
  align-items: center;
  background: #fff;
  border: 2px solid #bdc3c7;
  border-radius: 10px;
  padding: 0 12px;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-wrapper:focus-within {
  border-color: #e67e22;
  box-shadow: 0 0 0 3px rgba(230, 126, 34, 0.3);
}

.currency-symbol {
  font-weight: 600;
  color: #7f8c8d;
  margin-right: 4px;
  font-size: 1.1rem;
}

input[type="number"] {
  font-size: 1.1rem;
  padding: 12px 0;
  border: none;
  outline: none;
  width: 100%;
  background: transparent;
  color: #2c3e50;
  font-family: inherit;
}

input[type="number"]::placeholder {
  color: #bdc3c7;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input[type="number"] {
  -moz-appearance: textfield;
}

button {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: inherit;
  color: #fff;
  background: #e67e22;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-top: 8px;
}

button:hover {
  background: #d35400;
}

button:active {
  transform: scale(0.98);
}

button:focus-visible {
  outline: 3px solid #2c3e50;
  outline-offset: 2px;
}

.result {
  margin-top: 28px;
  border-top: 2px solid #bdc3c7;
  padding-top: 20px;
}

.result h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: #2c3e50;
}

.change-amount {
  font-size: 1.5rem;
  font-weight: 700;
  color: #27ae60;
  margin-bottom: 16px;
}

.breakdown-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.breakdown-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #fff;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 1.05rem;
  border-left: 4px solid #e67e22;
}

.breakdown-list li .denom {
  font-weight: 600;
  color: #2c3e50;
}

.breakdown-list li .count {
  font-weight: 700;
  color: #e67e22;
}

.error {
  margin-top: 20px;
  padding: 12px 16px;
  background: #fdecea;
  color: #c0392b;
  border-radius: 8px;
  font-weight: 600;
  border-left: 4px solid #c0392b;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  body {
    font-size: 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('change-form');
  const priceInput = document.getElementById('price');
  const paidInput = document.getElementById('paid');
  const resultDiv = document.getElementById('result');
  const changeAmountEl = document.getElementById('change-amount');
  const breakdownList = document.getElementById('breakdown-list');
  const errorEl = document.getElementById('error-message');

  const DENOMINATIONS = [20, 10, 5, 2, 1, 0.50, 0.20, 0.10, 0.05];

  function toCents(value) {
    return Math.round(value * 100);
  }

  function formatCurrency(amount) {
    return '£' + amount.toFixed(2);
  }

  function calculateBreakdown(changeCents) {
    const breakdown = [];
    let remaining = changeCents;

    for (const denom of DENOMINATIONS) {
      const denomCents = toCents(denom);
      const count = Math.floor(remaining / denomCents);
      if (count > 0) {
        breakdown.push({ denomination: denom, count });
        remaining -= count * denomCents;
      }
    }

    return breakdown;
  }

  function showError(message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
    resultDiv.hidden = true;
  }

  function clearError() {
    errorEl.hidden = true;
    errorEl.textContent = '';
  }

  function displayResult(changeCents, breakdown) {
    const changeAmount = changeCents / 100;
    changeAmountEl.textContent = formatCurrency(changeAmount);

    breakdownList.innerHTML = '';
    for (const item of breakdown) {
      const li = document.createElement('li');
      const denomSpan = document.createElement('span');
      denomSpan.className = 'denom';
      denomSpan.textContent = formatCurrency(item.denomination);
      const countSpan = document.createElement('span');
      countSpan.className = 'count';
      countSpan.textContent = '× ' + item.count;
      li.appendChild(denomSpan);
      li.appendChild(countSpan);
      breakdownList.appendChild(li);
    }

    if (breakdown.length === 0) {
      const li = document.createElement('li');
      li.textContent = 'No change needed';
      breakdownList.appendChild(li);
    }

    resultDiv.hidden = false;
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    clearError();

    const price = parseFloat(priceInput.value);
    const paid = parseFloat(paidInput.value);

    if (isNaN(price) || isNaN(paid)) {
      showError('Please enter valid numbers for price and amount paid.');
      return;
    }

    if (price < 0 || paid < 0) {
      showError('Price and amount paid cannot be negative.');
      return;
    }

    if (paid < price) {
      showError('Insufficient payment. The amount paid must be at least the price.');
      return;
    }

    const priceCents = toCents(price);
    const paidCents = toCents(paid);
    const changeCents = paidCents - priceCents;

    if (changeCents === 0) {
      changeAmountEl.textContent = formatCurrency(0);
      breakdownList.innerHTML = '<li>No change needed</li>';
      resultDiv.hidden = false;
      return;
    }

    const breakdown = calculateBreakdown(changeCents);
    displayResult(changeCents, breakdown);
  });
});
